/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=product, operation=get
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Get an activity */
export type PipedriveV2ProductGetParams = {
  resource: 'product';
  operation: 'get';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the product to get
 * @default 0
 */
    productId?: number | Expression<number>;
/**
 * Whether to show raw Pipedrive field keys and option IDs instead of human-readable names in output
 * @default false
 */
    rawCustomFieldOutput?: boolean | Expression<boolean>;
};

export type PipedriveV2ProductGetOutput = {
  add_time?: string;
  billing_frequency?: string;
  billing_frequency_cycles?: unknown;
  category?: unknown;
  code?: string;
  custom_fields?: Record<string, unknown>;
  description?: string;
  id?: number;
  is_deleted?: boolean;
  is_linkable?: boolean;
  name?: string;
  owner_id?: number;
  prices?: Array<{
    cost?: number;
    currency?: string;
    direct_cost?: number;
    notes?: string;
    price?: number;
    product_id?: number;
  }>;
  tax?: number;
  unit?: string;
  update_time?: string;
  visible_to?: number;
};

export type PipedriveV2ProductGetNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  config: NodeConfig<PipedriveV2ProductGetParams> & { credentials?: Credentials };
  output?: Items<PipedriveV2ProductGetOutput>;
};